    },
    {
      "name": "MvPowerSeries.le_weightedOrder_smul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {a : R},\n  MvPowerSeries.weightedOrder w f ≤ MvPowerSeries.weightedOrder w (a • f)"
    },
    {
      "name": "PowerSeries.orderHom",
      "module_name": "Mathlib.RingTheory.PowerSeries.Order",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → [NoZeroDivisors R] → [Nontrivial R] → PowerSeries R →* Multiplicative ℕ∞"
    },
    {
      "name": "MvPowerSeries.le_order_smul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {f : MvPowerSeries σ R} {a : R}, f.order ≤ (a • f).order"
    },
    {
      "name": "PowerSeries.le_order_smul",
